"use client";

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { Clock, Mail, MessageSquare, Play, Plus, Zap, Workflow, RefreshCw, Trash2, Pause, PlayCircle } from 'lucide-react';
import apiClient from '@/lib/api';
import { toast } from '@/hooks/use-toast';
import { AppLayout } from '@/components/layout/AppLayout';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@/components/ui/select';
import {
  Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle,
} from '@/components/ui/dialog';

const PRESETS = [
  {
    type: 'inbox_digest',
    name: 'Daily Inbox Digest',
    icon: Mail,
    description: 'Read Gmail, summarize with AI, optionally post to Slack',
    defaultConfig: { max_emails: '10', slack_channel: '' },
  },
  {
    type: 'slack_alert',
    name: 'Slack Alert',
    icon: MessageSquare,
    description: 'Send a scheduled message to a Slack channel',
    defaultConfig: { channel: '', message: 'Hello from MultiAgent!' },
  },
  {
    type: 'integration_check',
    name: 'Integration Health Check',
    icon: RefreshCw,
    description: 'Test all integrations and alert Slack on failures',
    defaultConfig: { slack_channel: '' },
  },
  {
    type: 'workflow_run',
    name: 'Run Workflow',
    icon: Workflow,
    description: 'Execute a saved visual workflow on schedule',
    defaultConfig: {},
  },
];

const TYPE_LABELS: Record<string, string> = {
  inbox_digest: 'Inbox Digest',
  slack_alert: 'Slack Alert',
  integration_check: 'Health Check',
  workflow_run: 'Workflow Run',
};

export default function AutomationsPage() {
  const [automations, setAutomations] = useState<any[]>([]);
  const [workflows, setWorkflows] = useState<any[]>([]);
  const [showCreate, setShowCreate] = useState(false);
  const [preset, setPreset] = useState(PRESETS[0]);
  const [name, setName] = useState('');
  const [frequency, setFrequency] = useState('daily');
  const [config, setConfig] = useState<Record<string, string>>({});
  const [workflowId, setWorkflowId] = useState('');
  const [runningId, setRunningId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isCreating, setIsCreating] = useState(false);

  const load = async () => {
    setIsLoading(true);
    try {
      const [autoRes, wfRes] = await Promise.all([
        apiClient.getAutomations(),
        apiClient.getWorkflows(),
      ]);
      setAutomations((autoRes.data as any)?.results || autoRes.data || []);
      setWorkflows((wfRes.data as any)?.results || wfRes.data || []);
    } catch (e: any) {
      toast({ title: 'Failed to load automations', description: e?.message, variant: 'destructive' });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const openPreset = (p: typeof PRESETS[0]) => {
    setPreset(p);
    setName(p.name);
    setConfig(Object.fromEntries(Object.entries(p.defaultConfig).map(([k, v]) => [k, String(v)])));
    setWorkflowId('');
    setShowCreate(true);
  };

  const handleCreate = async () => {
    if (preset.type === 'workflow_run' && !workflowId) {
      toast({ title: 'Select a workflow', variant: 'destructive' });
      return;
    }
    setIsCreating(true);
    try {
      await apiClient.createAutomation({
        name,
        automation_type: preset.type,
        frequency,
        is_active: true,
        config: {
          ...config,
          max_emails: config.max_emails ? parseInt(config.max_emails) : 10,
        },
        workflow: preset.type === 'workflow_run' ? workflowId : null,
      });
      setShowCreate(false);
      await load();
      toast({ title: 'Automation created', description: 'It will run on the next scheduler tick.' });
    } catch (e: any) {
      toast({ title: 'Failed to create automation', description: e?.response?.data?.detail || e?.message, variant: 'destructive' });
    } finally {
      setIsCreating(false);
    }
  };

  const handleRun = async (id: string) => {
    setRunningId(id);
    try {
      const res = await apiClient.runAutomation(id);
      const data = res.data as any;
      await load();
      toast({
        title: data?.success ? 'Automation completed' : 'Automation failed',
        description: data?.result?.message || data?.result?.summary || undefined,
        variant: data?.success ? 'default' : 'destructive',
      });
    } catch (e: any) {
      toast({ title: 'Run failed', description: e?.message, variant: 'destructive' });
    } finally {
      setRunningId(null);
    }
  };

  const handleToggle = async (a: any) => {
    try {
      await apiClient.updateAutomation(a.id, { is_active: !a.is_active });
      await load();
      toast({ title: a.is_active ? 'Automation paused' : 'Automation resumed' });
    } catch (e: any) {
      toast({ title: 'Update failed', description: e?.message, variant: 'destructive' });
    }
  };

  const handleDelete = async (id: string) => {
    try {
      await apiClient.deleteAutomation(id);
      await load();
      toast({ title: 'Automation deleted' });
    } catch (e: any) {
      toast({ title: 'Delete failed', description: e?.message, variant: 'destructive' });
    }
  };

  return (
    <AppLayout>
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-3">
              <Clock className="h-8 w-8 text-primary" />
              Scheduled Automations
            </h1>
            <p className="text-muted-foreground mt-1">Daily digests, Slack alerts, and workflow schedules</p>
          </div>
          <Button onClick={() => openPreset(PRESETS[0])} className="gap-2">
            <Plus className="h-4 w-4" /> New Automation
          </Button>
        </div>

        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {PRESETS.map((p) => (
            <Card key={p.type} className="cursor-pointer hover:border-primary/50 transition-colors" onClick={() => openPreset(p)}>
              <CardContent className="p-5">
                <p.icon className="h-8 w-8 text-primary mb-3" />
                <h3 className="font-semibold">{p.name}</h3>
                <p className="text-sm text-muted-foreground mt-1">{p.description}</p>
              </CardContent>
            </Card>
          ))}
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Active Automations</CardTitle>
            <CardDescription>Runs automatically via background scheduler (every minute check)</CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            {isLoading ? (
              <p className="text-sm text-muted-foreground text-center py-8">Loading...</p>
            ) : automations.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-8">No automations yet. Create one above.</p>
            ) : automations.map((a) => (
              <div key={a.id} className="flex items-center gap-4 p-4 rounded-lg border">
                <Zap className="h-5 w-5 text-primary shrink-0" />
                <div className="flex-1 min-w-0">
                  <p className="font-medium">{a.name}</p>
                  <p className="text-sm text-muted-foreground">
                    {TYPE_LABELS[a.automation_type] || a.automation_type} • {a.frequency}
                    {a.next_run_at && ` • next: ${new Date(a.next_run_at).toLocaleString()}`}
                  </p>
                  {a.last_result?.message && (
                    <p className="text-xs text-muted-foreground mt-1 truncate">Last: {a.last_result.message}</p>
                  )}
                </div>
                <Badge variant={a.is_active ? 'default' : 'secondary'}>{a.is_active ? 'Active' : 'Paused'}</Badge>
                <Button size="sm" variant="ghost" onClick={() => handleToggle(a)} title={a.is_active ? 'Pause' : 'Resume'}>
                  {a.is_active ? <Pause className="h-4 w-4" /> : <PlayCircle className="h-4 w-4" />}
                </Button>
                <Button size="sm" variant="outline" className="gap-1" disabled={runningId === a.id} onClick={() => handleRun(a.id)}>
                  <Play className="h-3 w-3" />
                  {runningId === a.id ? 'Running...' : 'Run now'}
                </Button>
                <Button size="sm" variant="ghost" className="text-destructive" onClick={() => handleDelete(a.id)}>
                  <Trash2 className="h-4 w-4" />
                </Button>
              </div>
            ))}
          </CardContent>
        </Card>

        <Dialog open={showCreate} onOpenChange={setShowCreate}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Create {preset.name}</DialogTitle>
              <DialogDescription>{preset.description}</DialogDescription>
            </DialogHeader>
            <div className="space-y-4">
              <div className="space-y-2">
                <Label>Name</Label>
                <Input value={name} onChange={(e) => setName(e.target.value)} />
              </div>
              <div className="space-y-2">
                <Label>Frequency</Label>
                <Select value={frequency} onValueChange={setFrequency}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="hourly">Hourly</SelectItem>
                    <SelectItem value="daily">Daily</SelectItem>
                    <SelectItem value="weekly">Weekly</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              {preset.type === 'inbox_digest' && (
                <>
                  <div className="space-y-2">
                    <Label>Max emails</Label>
                    <Input value={config.max_emails || '10'} onChange={(e) => setConfig({ ...config, max_emails: e.target.value })} />
                  </div>
                  <div className="space-y-2">
                    <Label>Slack channel (optional)</Label>
                    <Input placeholder="#general" value={config.slack_channel || ''} onChange={(e) => setConfig({ ...config, slack_channel: e.target.value })} />
                  </div>
                </>
              )}
              {preset.type === 'slack_alert' && (
                <>
                  <div className="space-y-2">
                    <Label>Slack channel</Label>
                    <Input placeholder="#alerts" value={config.channel || ''} onChange={(e) => setConfig({ ...config, channel: e.target.value })} />
                  </div>
                  <div className="space-y-2">
                    <Label>Message</Label>
                    <Input value={config.message || ''} onChange={(e) => setConfig({ ...config, message: e.target.value })} />
                  </div>
                </>
              )}
              {preset.type === 'integration_check' && (
                <div className="space-y-2">
                  <Label>Slack channel for failures (optional)</Label>
                  <Input placeholder="#alerts" value={config.slack_channel || ''} onChange={(e) => setConfig({ ...config, slack_channel: e.target.value })} />
                </div>
              )}
              {preset.type === 'workflow_run' && (
                <div className="space-y-2">
                  <Label>Workflow</Label>
                  <Select value={workflowId} onValueChange={setWorkflowId}>
                    <SelectTrigger><SelectValue placeholder="Select workflow" /></SelectTrigger>
                    <SelectContent>
                      {workflows.length === 0 ? (
                        <SelectItem value="_none" disabled>No saved workflows — create one in Workflows</SelectItem>
                      ) : workflows.map((w: any) => (
                        <SelectItem key={w.id} value={w.id}>{w.name}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setShowCreate(false)}>Cancel</Button>
              <Button onClick={handleCreate} disabled={isCreating || !name.trim()}>
                {isCreating ? 'Creating...' : 'Create'}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </motion.div>
    </AppLayout>
  );
}

"use client";

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  MessageSquare,
  Send,
  Paperclip,
  User,
  MoreVertical,
  Trash2,
  Copy,
  Check,
  RefreshCw,
  ThumbsUp,
  ThumbsDown,
  Plus,
  Search,
  Sparkles,
  Zap,
  Download,
  Star,
  Archive,
  Pin,
} from 'lucide-react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { oneDark } from 'react-syntax-highlighter/dist/esm/styles/prism';
import { cn } from '@/lib/utils';
import { getSessions, getMessages, sendMessage, getAgents, createSession, addAgentToSession } from '@/lib/api';

// Removed hardcoded agents, conversations, and messages

export default function ChatPage() {
  const [messages, setMessages] = useState<any[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  
  const [apiAgents, setApiAgents] = useState<any[]>([]);
  const [apiConversations, setApiConversations] = useState<any[]>([]);
  
  const [selectedAgent, setSelectedAgent] = useState<any>(null);
  const [selectedConversation, setSelectedConversation] = useState<any>(null);
  
  const [copied, setCopied] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Initial load
  useEffect(() => {
    const loadData = async () => {
      try {
        const [agentsRes, sessionsRes] = await Promise.all([
          getAgents(),
          getSessions()
        ]);
        
        const agents = (agentsRes as any).results || [];
        const sessions = ((sessionsRes as any).results || []).map((s: any) => ({
          ...s,
          title: s.name || 'Conversation',
          agent: s.agents && s.agents.length > 0 ? s.agents[0].name : 'Orchestrator',
          agentId: s.agents && s.agents.length > 0 ? s.agents[0].id : null,
          lastMessage: s.status || 'Active',
          time: new Date(s.created_at).toLocaleDateString(),
          unread: 0,
          pinned: false
        }));
        
        setApiAgents(agents);
        setApiConversations(sessions);
        
        if (agents.length > 0) setSelectedAgent(agents[0]);
        if (sessions.length > 0) setSelectedConversation(sessions[0]);
      } catch (err) {
        console.error('Failed to load chat data:', err);
      }
    };
    loadData();
  }, []);

  // Load messages when conversation changes
  useEffect(() => {
    const loadConversationMessages = async () => {
      if (!selectedConversation?.id) return;
      try {
        const msgsRes = await getMessages(selectedConversation.id);
        const msgs = (msgsRes as any).results || [];
        // Map backend messages to UI format
        setMessages(msgs.map((m: any) => ({
          id: m.id,
          role: m.sender_name ? 'user' : 'assistant',
          content: m.content || m.metadata?.content || 'No content',
          timestamp: new Date(m.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          agent: m.sender_name ? undefined : (selectedAgent?.name || 'Agent')
        })));
      } catch (err) {
        console.error('Failed to load messages:', err);
      }
    };
    loadConversationMessages();
  }, [selectedConversation?.id]);

  const handleSend = async () => {
    if (!input.trim()) return;
    
    let activeSession = selectedConversation;
    if (!activeSession) {
      try {
        activeSession = await createSession({ name: `Chat with ${selectedAgent?.name || 'Agent'}` });
        
        // If an agent is selected, add it to the session in the backend
        if (selectedAgent && selectedAgent.id) {
          try {
            await addAgentToSession(activeSession.id, selectedAgent.id);
          } catch (e) { console.error('Failed to link agent:', e); }
        }

        activeSession = {
          ...activeSession,
          title: activeSession.name || 'New Conversation',
          agent: selectedAgent?.name || 'Orchestrator',
          agentId: selectedAgent?.id || null,
          lastMessage: 'Started',
          time: new Date().toLocaleTimeString(),
          unread: 0,
          pinned: false
        };
        setApiConversations(prev => [activeSession, ...prev]);
        setSelectedConversation(activeSession);
      } catch (err) {
        console.error('Failed to create session:', err);
        return;
      }
    }

    const userMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    };

    setMessages(prev => [...prev, userMessage]);
    const messageContent = input;
    setInput('');
    setIsTyping(true);

    try {
      // Link selected agent to session so the backend routes to the right specialist
      if (selectedAgent?.id) {
        try {
          await addAgentToSession(activeSession.id, selectedAgent.id);
        } catch {
          // Agent may already be linked to this session
        }
      }

      const responseMsg = await sendMessage(activeSession.id, {
        content: messageContent,
        message_type: 'text',
        metadata: { agent_id: selectedAgent?.id },
      });
      
      const aiMessage = {
        id: responseMsg.id || (Date.now() + 1).toString(),
        role: 'assistant',
        content: responseMsg.content || responseMsg.metadata?.content || responseMsg.metadata?.response || 'Done.',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        agent: selectedAgent?.name || 'Agent',
      };
      
      setMessages(prev => [...prev, aiMessage]);
      setApiConversations(prev => prev.map(c => c.id === activeSession.id ? { ...c, lastMessage: responseMsg.content } : c));
    } catch (err: any) {
      console.error('Failed to send message:', err);
      const detail = err?.response?.data?.detail || err?.response?.data?.error || err?.message;
      const errorMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: detail
          ? `Sorry, I encountered an error: ${typeof detail === 'string' ? detail : JSON.stringify(detail)}`
          : 'Sorry, I encountered an error processing your request. The request may have timed out — try again.',
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        agent: 'System',
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsTyping(false);
    }
  };

  const copyToClipboard = (id: string, text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(id);
    setTimeout(() => setCopied(null), 2000);
  };

  return (
    <AppLayout>
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="h-[calc(100vh-8rem)] flex gap-6"
      >
        {/* Sidebar - Conversations */}
        <Card className="w-80 shrink-0 flex flex-col">
          <CardHeader className="pb-3">
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg flex items-center gap-2">
                <MessageSquare className="h-5 w-5" />
                Chats
              </CardTitle>
              <Button size="icon" variant="ghost" onClick={() => {
                setSelectedConversation(null);
                setMessages([]);
              }}>
                <Plus className="h-4 w-4" />
              </Button>
            </div>
            <div className="relative mt-2">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input placeholder="Search conversations..." className="pl-10" />
            </div>
          </CardHeader>
          <CardContent className="flex-1 p-0 overflow-hidden">
            <ScrollArea className="h-full">
              <div className="p-2 space-y-1">
                {apiConversations
                  .filter(conv => !selectedAgent || conv.agentId === selectedAgent.id || conv.agent === 'Orchestrator')
                  .map((conv) => (
                  <motion.button
                    key={conv.id}
                    onClick={() => setSelectedConversation(conv)}
                    className={cn(
                      "w-full flex items-start gap-3 p-3 rounded-lg text-left transition-colors",
                      selectedConversation?.id === conv.id
                        ? "bg-primary/10 border border-primary/20"
                        : "hover:bg-muted/50"
                    )}
                    whileHover={{ scale: 1.01 }}
                    whileTap={{ scale: 0.99 }}
                  >
                    <Avatar className="h-10 w-10">
                      <AvatarFallback className="text-lg">
                        {apiAgents.find(a => a.name === conv.agent)?.avatar || '🤖'}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between">
                        <span className="font-medium truncate flex items-center gap-1">
                          {conv.pinned && <Pin className="h-3 w-3 text-primary" />}
                          {conv.title}
                        </span>
                        <span className="text-xs text-muted-foreground">{conv.time}</span>
                      </div>
                      <p className="text-sm text-muted-foreground truncate">{conv.lastMessage}</p>
                    </div>
                    {conv.unread > 0 && (
                      <Badge className="h-5 px-1.5">{conv.unread}</Badge>
                    )}
                  </motion.button>
                ))}
              </div>
            </ScrollArea>
          </CardContent>
        </Card>

        {/* Main Chat Area */}
        <Card className="flex-1 flex flex-col overflow-hidden">
          {/* Chat Header */}
          <CardHeader className="border-b shrink-0">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Avatar className="h-10 w-10">
                  <AvatarFallback className="text-lg">{selectedAgent?.avatar || 'A'}</AvatarFallback>
                </Avatar>
                <div>
                  <CardTitle className="text-lg flex items-center gap-2">
                    {selectedAgent?.name || 'Loading...'}
                    <Badge
                      variant="outline"
                      className={cn(
                        "text-xs",
                        selectedAgent?.status === 'online' && "text-green-500 border-green-500/30",
                        selectedAgent?.status === 'busy' && "text-yellow-500 border-yellow-500/30",
                        selectedAgent?.status === 'offline' && "text-muted-foreground"
                      )}
                    >
                      {selectedAgent?.status || 'offline'}
                    </Badge>
                  </CardTitle>
                  <CardDescription>{selectedAgent?.type || 'Unknown'} agent</CardDescription>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <Select
                  value={selectedAgent?.id || ''}
                  onValueChange={(id) => {
                    const agent = apiAgents.find(a => a.id === id);
                    if (agent) {
                      setSelectedAgent(agent);
                      setSelectedConversation(null);
                      setMessages([]);
                    }
                  }}
                >
                  <SelectTrigger className="w-40">
                    <SelectValue placeholder="Switch agent" />
                  </SelectTrigger>
                  <SelectContent>
                    {apiAgents.map(agent => (
                      <SelectItem key={agent.id} value={agent.id}>
                        <div className="flex items-center gap-2">
                          <span>{agent.avatar || '🤖'}</span>
                          <span>{agent.name}</span>
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button variant="ghost" size="icon">
                      <MoreVertical className="h-4 w-4" />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end">
                    <DropdownMenuItem>
                      <Star className="h-4 w-4 mr-2" />
                      Star conversation
                    </DropdownMenuItem>
                    <DropdownMenuItem>
                      <Archive className="h-4 w-4 mr-2" />
                      Archive
                    </DropdownMenuItem>
                    <DropdownMenuItem>
                      <Download className="h-4 w-4 mr-2" />
                      Export chat
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem className="text-destructive">
                      <Trash2 className="h-4 w-4 mr-2" />
                      Delete conversation
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </div>
            </div>
          </CardHeader>

          {/* Messages */}
          <CardContent className="flex-1 overflow-hidden p-0">
            <ScrollArea className="h-full p-4">
              <div className="space-y-6">
                <AnimatePresence>
                  {messages.map((message, index) => (
                    <motion.div
                      key={message.id}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: index * 0.05 }}
                      className={cn(
                        "flex gap-3",
                        message.role === 'user' && "flex-row-reverse"
                      )}
                    >
                      <Avatar className="h-8 w-8 shrink-0">
                        {message.role === 'assistant' ? (
                          <AvatarFallback className="text-sm bg-primary/10">
                            {selectedAgent.avatar}
                          </AvatarFallback>
                        ) : (
                          <AvatarFallback className="bg-muted">
                            <User className="h-4 w-4" />
                          </AvatarFallback>
                        )}
                      </Avatar>
                      <div className={cn(
                        "group max-w-[70%] space-y-1",
                        message.role === 'user' && "items-end"
                      )}>
                        <div className={cn(
                          "rounded-2xl px-4 py-2.5",
                          message.role === 'assistant'
                            ? "bg-muted"
                            : "bg-gradient-to-br from-indigo-600 to-purple-600 text-white"
                        )}>
                          {message.role === 'assistant' ? (
                            <div className="prose prose-sm dark:prose-invert max-w-none">
                              <ReactMarkdown 
                                remarkPlugins={[remarkGfm]}
                                components={{
                                  code: (props) => {
                                    const { className, children, node: _node, ref: _ref, ...rest } = props;
                                    const match = /language-(\w+)/.exec(className || '');
                                    const isInline = !match && !String(children).includes('\n');
                                    return !isInline && match ? (
                                      <SyntaxHighlighter
                                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                                        style={oneDark as any}
                                        language={match[1]}
                                        PreTag="div"
                                        className="rounded-md text-sm"
                                        {...rest}
                                      >
                                        {String(children).replace(/\n$/, '')}
                                      </SyntaxHighlighter>
                                    ) : (
                                      <code className="bg-muted px-1 py-0.5 rounded text-sm font-mono" {...rest}>
                                        {children}
                                      </code>
                                    );
                                  },
                                  h1: ({ children }) => <h1 className="text-lg font-bold mb-2 mt-4 first:mt-0">{children}</h1>,
                                  h2: ({ children }) => <h2 className="text-base font-bold mb-2 mt-3 first:mt-0">{children}</h2>,
                                  h3: ({ children }) => <h3 className="text-sm font-bold mb-1 mt-2 first:mt-0">{children}</h3>,
                                  p: ({ children }) => <p className="mb-2 last:mb-0">{children}</p>,
                                  ul: ({ children }) => <ul className="list-disc list-inside mb-2 space-y-1">{children}</ul>,
                                  ol: ({ children }) => <ol className="list-decimal list-inside mb-2 space-y-1">{children}</ol>,
                                  li: ({ children }) => <li className="ml-4">{children}</li>,
                                  strong: ({ children }) => <strong className="font-semibold">{children}</strong>,
                                  em: ({ children }) => <em className="italic">{children}</em>,
                                  blockquote: ({ children }) => <blockquote className="border-l-4 border-muted-foreground/30 pl-4 italic my-2">{children}</blockquote>
                                }}
                              >
                                {message.content}
                              </ReactMarkdown>
                            </div>
                          ) : (
                            <p className="text-sm whitespace-pre-wrap leading-relaxed">{message.content}</p>
                          )}
                        </div>
                        <div className={cn(
                          "flex items-center gap-2 px-2 opacity-0 group-hover:opacity-100 transition-opacity",
                          message.role === 'user' && "flex-row-reverse"
                        )}>
                          <span className="text-xs text-muted-foreground">{message.timestamp}</span>
                          {message.role === 'assistant' && (
                            <>
                              <TooltipProvider>
                                <Tooltip>
                                  <TooltipTrigger asChild>
                                    <Button
                                      variant="ghost"
                                      size="icon"
                                      className="h-6 w-6"
                                      onClick={() => copyToClipboard(message.id, message.content)}
                                    >
                                      {copied === message.id ? (
                                        <Check className="h-3 w-3 text-green-500" />
                                      ) : (
                                        <Copy className="h-3 w-3" />
                                      )}
                                    </Button>
                                  </TooltipTrigger>
                                  <TooltipContent>Copy</TooltipContent>
                                </Tooltip>
                              </TooltipProvider>
                              <Button variant="ghost" size="icon" className="h-6 w-6">
                                <ThumbsUp className="h-3 w-3" />
                              </Button>
                              <Button variant="ghost" size="icon" className="h-6 w-6">
                                <ThumbsDown className="h-3 w-3" />
                              </Button>
                              <Button variant="ghost" size="icon" className="h-6 w-6">
                                <RefreshCw className="h-3 w-3" />
                              </Button>
                            </>
                          )}
                        </div>
                      </div>
                    </motion.div>
                  ))}
                </AnimatePresence>

                {/* Typing Indicator */}
                {isTyping && (
                  <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex items-center gap-3"
                  >
                    <Avatar className="h-8 w-8">
                      <AvatarFallback className="text-sm bg-primary/10">
                        {selectedAgent.avatar}
                      </AvatarFallback>
                    </Avatar>
                    <div className="bg-muted rounded-2xl px-4 py-3">
                      <div className="flex gap-1">
                        <motion.span
                          animate={{ opacity: [0.4, 1, 0.4] }}
                          transition={{ duration: 1, repeat: Infinity }}
                          className="h-2 w-2 rounded-full bg-muted-foreground"
                        />
                        <motion.span
                          animate={{ opacity: [0.4, 1, 0.4] }}
                          transition={{ duration: 1, repeat: Infinity, delay: 0.2 }}
                          className="h-2 w-2 rounded-full bg-muted-foreground"
                        />
                        <motion.span
                          animate={{ opacity: [0.4, 1, 0.4] }}
                          transition={{ duration: 1, repeat: Infinity, delay: 0.4 }}
                          className="h-2 w-2 rounded-full bg-muted-foreground"
                        />
                      </div>
                    </div>
                  </motion.div>
                )}

                <div ref={messagesEndRef} />
              </div>
            </ScrollArea>
          </CardContent>

          {/* Input Area */}
          <div className="border-t p-4 shrink-0">
            <div className="flex items-end gap-3">
              <div className="flex-1 relative">
                <Textarea
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder="Type your message..."
                  className="min-h-[60px] max-h-[200px] resize-none pr-12"
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSend();
                    }
                  }}
                />
                <div className="absolute right-2 bottom-2 flex items-center gap-1">
                  <TooltipProvider>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <Button variant="ghost" size="icon" className="h-8 w-8">
                          <Paperclip className="h-4 w-4" />
                        </Button>
                      </TooltipTrigger>
                      <TooltipContent>Attach file</TooltipContent>
                    </Tooltip>
                  </TooltipProvider>
                </div>
              </div>
              <Button onClick={handleSend} size="lg" className="h-[60px] gap-2">
                <Send className="h-5 w-5" />
                Send
              </Button>
            </div>
            <div className="flex items-center gap-2 mt-2">
              <Badge variant="outline" className="text-xs gap-1">
                <Sparkles className="h-3 w-3" />
                GPT-4 Turbo
              </Badge>
              <Badge variant="outline" className="text-xs gap-1">
                <Zap className="h-3 w-3" />
                Fast mode
              </Badge>
            </div>
          </div>
        </Card>
      </motion.div>
    </AppLayout>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { motion, type Variants } from 'framer-motion';
import {
  Bot,
  Workflow,
  Activity,
  Zap,
  ArrowUp,
  ArrowDown,
  Clock,
  CheckCircle2,
  MessageSquare,
  BarChart3,
  Sparkles,
  Play,
  Pause,
  RefreshCw,
  Plus,
  ChevronRight,
  Brain,
  Eye,
  Cpu,
  Database,
  Grid3X3,
  List,
} from 'lucide-react';
import apiClient from '@/lib/api';
import { AppLayout } from '@/components/layout/AppLayout';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { cn } from '@/lib/utils';

// Animation variants
const containerVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1,
    },
  },
};

const itemVariants: Variants = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.5,
      ease: [0.42, 0, 0.58, 1],
    },
  },
};

// Agent types with icons
const agentTypes = [
  { type: 'orchestrator', icon: Brain, color: 'text-purple-500', bg: 'bg-purple-500/10' },
  { type: 'vision', icon: Eye, color: 'text-blue-500', bg: 'bg-blue-500/10' },
  { type: 'reasoning', icon: Cpu, color: 'text-green-500', bg: 'bg-green-500/10' },
  { type: 'action', icon: Zap, color: 'text-orange-500', bg: 'bg-orange-500/10' },
  { type: 'memory', icon: Database, color: 'text-cyan-500', bg: 'bg-cyan-500/10' },
  { type: 'custom', icon: Cpu, color: 'text-gray-500', bg: 'bg-gray-500/10' },
];

// Quick actions
const quickActions = [
  { title: 'Create Agent', icon: Bot, href: '/agents', gradient: 'from-indigo-500 to-purple-500' },
  { title: 'Build Workflow', icon: Workflow, href: '/workflows', gradient: 'from-blue-500 to-cyan-500' },
  { title: 'Start Chat', icon: MessageSquare, href: '/chat', gradient: 'from-green-500 to-emerald-500' },
  { title: 'View Analytics', icon: BarChart3, href: '/analytics', gradient: 'from-orange-500 to-amber-500' },
];

export default function DashboardPage() {
  const router = useRouter();
  const [agents, setAgents] = useState<any[]>([]);
  const [dashboardData, setDashboardData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  const loadData = async () => {
    setIsLoading(true);
    try {
      const [agentsRes, dashboardRes] = await Promise.all([
        apiClient.getAgents(),
        apiClient.getAnalyticsDashboard()
      ]);
      setAgents(agentsRes.results || agentsRes || []);
      setDashboardData(dashboardRes);
    } catch (error) {
      console.error('Failed to load dashboard data:', error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const stats = dashboardData ? [
    {
      title: 'Active Agents',
      value: (dashboardData.overview?.agents?.by_status?.active || 0).toString(),
      change: `Total ${dashboardData.overview?.agents?.total || 0}`,
      changeType: 'positive' as const,
      icon: Bot,
      gradient: 'from-indigo-500 to-purple-500',
      description: 'Running workflows',
    },
    {
      title: 'Tasks Completed',
      value: (dashboardData.overview?.tasks?.by_status?.completed || 0).toString(),
      change: `${((dashboardData.overview?.tasks?.success_rate || 0) * 100).toFixed(1)}%`,
      changeType: 'positive' as const,
      icon: CheckCircle2,
      gradient: 'from-green-500 to-emerald-500',
      description: 'Success rate',
    },
    {
      title: 'Total Tasks',
      value: (dashboardData.overview?.tasks?.total || 0).toString(),
      change: 'Active',
      changeType: 'positive' as const,
      icon: Zap,
      gradient: 'from-orange-500 to-amber-500',
      description: 'All tasks',
    },
    {
      title: 'Total Messages',
      value: (dashboardData.overview?.messages?.total || 0).toString(),
      change: 'Activity',
      changeType: 'positive' as const,
      icon: Activity,
      gradient: 'from-blue-500 to-cyan-500',
      description: 'In sessions',
    },
  ] : [
    { title: 'Active Agents', value: '-', change: '-', changeType: 'positive' as const, icon: Bot, gradient: 'from-indigo-500 to-purple-500', description: 'Loading...' },
    { title: 'Tasks Completed', value: '-', change: '-', changeType: 'positive' as const, icon: CheckCircle2, gradient: 'from-green-500 to-emerald-500', description: 'Loading...' },
    { title: 'Total Tasks', value: '-', change: '-', changeType: 'positive' as const, icon: Zap, gradient: 'from-orange-500 to-amber-500', description: 'Loading...' },
    { title: 'Total Messages', value: '-', change: '-', changeType: 'positive' as const, icon: Activity, gradient: 'from-blue-500 to-cyan-500', description: 'Loading...' },
  ];

  const getAgentTypeInfo = (type: string) => {
    return agentTypes.find(t => t.type === type) || agentTypes[0];
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'bg-green-500';
      case 'processing': return 'bg-blue-500 animate-pulse';
      case 'error': return 'bg-red-500';
      default: return 'bg-slate-400';
    }
  };

  return (
    <AppLayout>
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="space-y-6"
      >
        {/* Header */}
        <motion.div variants={itemVariants} className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-3">
              <Sparkles className="h-8 w-8 text-primary" />
              Welcome back, John
            </h1>
            <p className="text-muted-foreground mt-1">
              Here&apos;s what&apos;s happening with your AI agents today.
            </p>
          </div>
          <div className="flex items-center gap-3">
            <Button variant="outline" className="gap-2" onClick={loadData}>
              <RefreshCw className={`h-4 w-4 ${isLoading ? 'animate-spin' : ''}`} />
              Refresh
            </Button>
            <Button 
              className="gap-2 bg-gradient-to-r from-indigo-500 to-purple-500 hover:opacity-90"
              onClick={() => router.push('/agents')}
            >
              <Plus className="h-4 w-4" />
              New Agent
            </Button>
          </div>
        </motion.div>

        {/* Stats Grid */}
        <motion.div variants={itemVariants} className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {stats.map((stat, index) => (
            <motion.div
              key={stat.title}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
            >
              <Card className="relative overflow-hidden group hover:shadow-lg transition-all duration-300">
                {/* Gradient Background */}
                <div className={cn(
                  "absolute inset-0 opacity-0 group-hover:opacity-5 transition-opacity bg-gradient-to-br",
                  stat.gradient
                )} />
                
                <CardContent className="p-6">
                  <div className="flex items-center justify-between">
                    <div className={cn(
                      "flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br",
                      stat.gradient
                    )}>
                      <stat.icon className="h-6 w-6 text-white" />
                    </div>
                    <Badge 
                      variant={stat.changeType === 'positive' ? 'default' : 'destructive'}
                      className="flex items-center gap-1"
                    >
                      {stat.changeType === 'positive' ? (
                        <ArrowUp className="h-3 w-3" />
                      ) : (
                        <ArrowDown className="h-3 w-3" />
                      )}
                      {stat.change}
                    </Badge>
                  </div>
                  <div className="mt-4">
                    <h3 className="text-3xl font-bold">{stat.value}</h3>
                    <p className="text-sm text-muted-foreground">{stat.title}</p>
                    <p className="text-xs text-muted-foreground mt-1">{stat.description}</p>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </motion.div>

        {/* Quick Actions */}
        <motion.div variants={itemVariants}>
          <h2 className="text-lg font-semibold mb-4">Quick Actions</h2>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {quickActions.map((action, index) => (
              <motion.a
                key={action.title}
                href={action.href}
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: 0.3 + index * 0.1 }}
                whileHover={{ scale: 1.02, y: -2 }}
                whileTap={{ scale: 0.98 }}
                className="group"
              >
                <Card className="relative overflow-hidden cursor-pointer hover:shadow-lg transition-all duration-300 border-dashed">
                  <div className={cn(
                    "absolute inset-0 opacity-0 group-hover:opacity-10 transition-opacity bg-gradient-to-br",
                    action.gradient
                  )} />
                  <CardContent className="flex items-center gap-4 p-4">
                    <div className={cn(
                      "flex h-10 w-10 items-center justify-center rounded-lg bg-gradient-to-br",
                      action.gradient
                    )}>
                      <action.icon className="h-5 w-5 text-white" />
                    </div>
                    <span className="font-medium">{action.title}</span>
                    <ChevronRight className="h-4 w-4 ml-auto text-muted-foreground group-hover:translate-x-1 transition-transform" />
                  </CardContent>
                </Card>
              </motion.a>
            ))}
          </div>
        </motion.div>

        {/* Main Content Grid */}
        <div className="grid gap-6 lg:grid-cols-3">
          {/* Active Agents */}
          <motion.div variants={itemVariants} className="lg:col-span-2">
            <Card className="h-full">
              <CardHeader className="flex flex-row items-center justify-between">
                <div>
                  <CardTitle>Active Agents</CardTitle>
                  <CardDescription>Monitor and manage your AI agents</CardDescription>
                </div>
                <Button variant="ghost" size="sm" className="gap-2">
                  View All
                  <ChevronRight className="h-4 w-4" />
                </Button>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {agents.map((agent, index) => {
                    const typeInfo = getAgentTypeInfo(agent.type);
                    const Icon = typeInfo.icon;
                    
                    return (
                      <motion.div
                        key={agent.id}
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: 0.4 + index * 0.1 }}
                        className="flex items-center gap-4 p-4 rounded-xl bg-muted/50 hover:bg-muted transition-colors group"
                      >
                        <div className={cn("flex h-10 w-10 items-center justify-center rounded-lg", typeInfo.bg)}>
                          <Icon className={cn("h-5 w-5", typeInfo.color)} />
                        </div>
                        
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <span className="font-medium truncate">{agent.name}</span>
                            <span className={cn("h-2 w-2 rounded-full", getStatusColor(agent.status))} />
                          </div>
                          <div className="flex items-center gap-4 text-sm text-muted-foreground">
                            <span className="capitalize">{agent.type}</span>
                            <span>{agent.tasks} tasks</span>
                          </div>
                        </div>

                        <div className="hidden sm:flex items-center gap-4">
                          <div className="text-right">
                            <div className="text-sm font-medium">{agent.tasks || 0} tasks</div>
                            <div className="text-xs text-muted-foreground">Processed</div>
                          </div>
                          <Progress value={agent.performance_metrics?.success_rate || 100} className="w-20 h-2" />
                        </div>

                        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          {agent.status === 'active' ? (
                            <Button variant="ghost" size="icon" className="h-8 w-8">
                              <Pause className="h-4 w-4" />
                            </Button>
                          ) : (
                            <Button variant="ghost" size="icon" className="h-8 w-8">
                              <Play className="h-4 w-4" />
                            </Button>
                          )}
                        </div>
                      </motion.div>
                    );
                  })}
                </div>
              </CardContent>
            </Card>
          </motion.div>

          {/* Recent Activity */}
          <motion.div variants={itemVariants}>
            <Card className="h-full">
              <CardHeader>
                <CardTitle>Recent Activity</CardTitle>
                <CardDescription>Latest updates from your agents</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {(dashboardData?.recent_activities || []).map((activity: any, index: number) => (
                    <motion.div
                      key={activity.id || index}
                      initial={{ opacity: 0, x: 20 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: 0.5 + index * 0.1 }}
                      className="flex items-start gap-3"
                    >
                      <div className={cn(
                        "mt-1 h-2 w-2 rounded-full shrink-0",
                        activity.status === 'success' && "bg-green-500",
                        activity.status === 'warning' && "bg-yellow-500",
                        activity.status === 'info' && "bg-blue-500",
                        activity.status === 'error' && "bg-red-500"
                      )} />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium">{activity.action}</p>
                        <p className="text-xs text-muted-foreground truncate">{activity.agent}</p>
                      </div>
                      <div className="flex items-center gap-1 text-xs text-muted-foreground">
                        <Clock className="h-3 w-3" />
                        {activity.time}
                      </div>
                    </motion.div>
                  ))}
                  {(!dashboardData?.recent_activities || dashboardData.recent_activities.length === 0) && (
                    <div className="text-center text-muted-foreground text-sm py-4">
                      No recent activity.
                    </div>
                  )}
                </div>

                <Button variant="ghost" className="w-full mt-4 text-muted-foreground">
                  View All Activity
                  <ChevronRight className="h-4 w-4 ml-2" />
                </Button>
              </CardContent>
            </Card>
          </motion.div>
        </div>

        {/* Performance Overview */}
        <motion.div variants={itemVariants}>
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle>Performance Overview</CardTitle>
                  <CardDescription>System metrics and health status</CardDescription>
                </div>
                <Tabs defaultValue="24h" className="w-auto">
                  <TabsList>
                    <TabsTrigger value="24h">24h</TabsTrigger>
                    <TabsTrigger value="7d">7d</TabsTrigger>
                    <TabsTrigger value="30d">30d</TabsTrigger>
                  </TabsList>
                </Tabs>
              </div>
            </CardHeader>
            <CardContent>
              <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
                {[
                  { label: 'CPU Usage', value: 45, color: 'bg-blue-500' },
                  { label: 'Memory', value: 62, color: 'bg-purple-500' },
                  { label: 'API Quota', value: 78, color: 'bg-green-500' },
                  { label: 'Storage', value: 34, color: 'bg-orange-500' },
                ].map((metric, index) => (
                  <motion.div
                    key={metric.label}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.6 + index * 0.1 }}
                    className="space-y-2"
                  >
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-muted-foreground">{metric.label}</span>
                      <span className="font-medium">{metric.value}%</span>
                    </div>
                    <div className="h-2 rounded-full bg-muted overflow-hidden">
                      <motion.div
                        className={cn("h-full rounded-full", metric.color)}
                        initial={{ width: 0 }}
                        animate={{ width: `${metric.value}%` }}
                        transition={{ duration: 1, delay: 0.8 + index * 0.1 }}
                      />
                    </div>
                  </motion.div>
                ))}
              </div>

              {/* System Status */}
              <div className="mt-6 pt-6 border-t">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <span className="relative flex h-3 w-3">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
                    </span>
                    <span className="text-sm font-medium">All Systems Operational</span>
                  </div>
                  <Button variant="outline" size="sm">
                    View Status Page
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>
      </motion.div>
    </AppLayout>
  );
}

