"use client";

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import ReactFlow, {
  Node,
  Edge,
  Controls,
  Background,
  MiniMap,
  useNodesState,
  useEdgesState,
  addEdge,
  Connection,
  MarkerType,
  Panel,
  NodeTypes,
  Handle,
  Position,
} from 'reactflow';
import 'reactflow/dist/style.css';
import {
  Workflow,
  Play,
  Save,
  Download,
  Upload,
  Undo,
  Redo,
  ZoomIn,
  ZoomOut,
  Maximize2,
  Bot,
  GitBranch,
  Timer,
  ArrowRight,
  Trash2,
  Copy,
  Layers,
  ChevronRight,
  Zap,
  Filter,
  Globe,
} from 'lucide-react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/components/ui/tabs';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { ScrollArea } from '@/components/ui/scroll-area';
import apiClient from '@/lib/api';
import { toast } from '@/hooks/use-toast';
import { cn } from '@/lib/utils';

// Node types configuration
const nodeTypesConfig = {
  trigger: { icon: Zap, color: 'bg-green-500', label: 'Trigger' },
  agent: { icon: Bot, color: 'bg-indigo-500', label: 'Agent' },
  condition: { icon: GitBranch, color: 'bg-yellow-500', label: 'Condition' },
  action: { icon: ArrowRight, color: 'bg-blue-500', label: 'Action' },
  transform: { icon: Filter, color: 'bg-purple-500', label: 'Transform' },
  integration: { icon: Globe, color: 'bg-cyan-500', label: 'Integration' },
  delay: { icon: Timer, color: 'bg-orange-500', label: 'Delay' },
  loop: { icon: Layers, color: 'bg-pink-500', label: 'Loop' },
};

// Custom Node Component
const CustomNode = ({ data, selected }: { data: { nodeType: string; label: string; description?: string; [key: string]: unknown }; selected: boolean }) => {
  const config = nodeTypesConfig[data.nodeType as keyof typeof nodeTypesConfig] || nodeTypesConfig.action;
  const Icon = config.icon;

  return (
    <div className={cn(
      "relative rounded-xl border-2 bg-background shadow-lg transition-all duration-200 min-w-[200px]",
      selected ? "border-primary ring-4 ring-primary/20" : "border-border hover:border-primary/50"
    )}>
      {/* Input Handle */}
      {data.nodeType !== 'trigger' && (
        <Handle
          type="target"
          position={Position.Top}
          className="!w-3 !h-3 !bg-primary !border-2 !border-background"
        />
      )}

      {/* Node Header */}
      <div className={cn("flex items-center gap-2 p-3 rounded-t-lg", config.color)}>
        <Icon className="h-4 w-4 text-white" />
        <span className="text-sm font-medium text-white">{config.label}</span>
      </div>

      {/* Node Content */}
      <div className="p-3">
        <h4 className="font-medium text-sm mb-1">{data.label}</h4>
        {data.nodeType === 'integration' && !!data.tool_name && (
          <p className="text-xs font-mono text-cyan-600 dark:text-cyan-400">{String(data.tool_name)}</p>
        )}
        {data.description && (
          <p className="text-xs text-muted-foreground">{data.description}</p>
        )}
      </div>

      {/* Output Handle */}
      <Handle
        type="source"
        position={Position.Bottom}
        className="!w-3 !h-3 !bg-primary !border-2 !border-background"
      />

      {/* Multiple outputs for condition nodes */}
      {data.nodeType === 'condition' && (
        <>
          <Handle
            type="source"
            position={Position.Right}
            id="true"
            className="!w-3 !h-3 !bg-green-500 !border-2 !border-background"
            style={{ top: '50%' }}
          />
          <Handle
            type="source"
            position={Position.Left}
            id="false"
            className="!w-3 !h-3 !bg-red-500 !border-2 !border-background"
            style={{ top: '50%' }}
          />
        </>
      )}
    </div>
  );
};

const nodeTypes: NodeTypes = {
  custom: CustomNode,
};

// Initial nodes
const initialNodes: Node[] = [
  {
    id: '1',
    type: 'custom',
    position: { x: 400, y: 50 },
    data: { label: 'Webhook Trigger', nodeType: 'trigger', description: 'Starts when webhook is received' },
  },
  {
    id: '2',
    type: 'custom',
    position: { x: 400, y: 180 },
    data: { label: 'Orchestrator Agent', nodeType: 'agent', description: 'Routes to appropriate agent' },
  },
  {
    id: '3',
    type: 'custom',
    position: { x: 400, y: 310 },
    data: { label: 'Check Intent', nodeType: 'condition', description: 'Analyze user intent' },
  },
  {
    id: '4',
    type: 'custom',
    position: { x: 200, y: 440 },
    data: { label: 'Vision Agent', nodeType: 'agent', description: 'Process visual content' },
  },
  {
    id: '5',
    type: 'custom',
    position: { x: 600, y: 440 },
    data: { label: 'Reasoning Agent', nodeType: 'agent', description: 'Handle text queries' },
  },
];

const initialEdges: Edge[] = [
  { id: 'e1-2', source: '1', target: '2', markerEnd: { type: MarkerType.ArrowClosed } },
  { id: 'e2-3', source: '2', target: '3', markerEnd: { type: MarkerType.ArrowClosed } },
  { id: 'e3-4', source: '3', sourceHandle: 'false', target: '4', markerEnd: { type: MarkerType.ArrowClosed }, label: 'Image' },
  { id: 'e3-5', source: '3', sourceHandle: 'true', target: '5', markerEnd: { type: MarkerType.ArrowClosed }, label: 'Text' },
];

// Fallback templates when API has none
const fallbackWorkflowTemplates = [
  { id: '1', name: 'Integration Pipeline', category: 'integration', nodes: 3 },
  { id: '2', name: 'Gmail → Slack Alert', category: 'automation', nodes: 4 },
];

export default function WorkflowsPage() {
  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);
  const [selectedNode, setSelectedNode] = useState<Node | null>(null);
  const [isPanelOpen, setIsPanelOpen] = useState(false);
  const [workflowName, setWorkflowName] = useState('My Workflow');
  const [workflowId, setWorkflowId] = useState<string | null>(null);
  const [savedWorkflows, setSavedWorkflows] = useState<any[]>([]);
  const [workflowTemplates, setWorkflowTemplates] = useState<any[]>(fallbackWorkflowTemplates);
  const [integrationTools, setIntegrationTools] = useState<any[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [isExecuting, setIsExecuting] = useState(false);
  const [paramsJson, setParamsJson] = useState('{}');
  const reactFlowWrapper = useRef<HTMLDivElement>(null);

  const loadSavedWorkflows = async () => {
    try {
      const res = await apiClient.getWorkflows();
      setSavedWorkflows((res.data as any)?.results || res.data || []);
    } catch (e) {
      console.error(e);
    }
  };

  useEffect(() => {
    loadSavedWorkflows();
    apiClient.getWorkflowTemplates().then((res) => {
      const list = (res.data as any)?.results || res.data || [];
      if (list.length > 0) setWorkflowTemplates(list);
    }).catch(console.error);
    apiClient.getIntegrationTools().then((res) => {
      setIntegrationTools((res.data as any)?.results || []);
    }).catch(console.error);
  }, []);

  const onConnect = useCallback(
    (params: Connection) => {
      setEdges((eds) => addEdge({ ...params, markerEnd: { type: MarkerType.ArrowClosed } }, eds));
    },
    [setEdges]
  );

  const onNodeClick = useCallback((event: React.MouseEvent, node: Node) => {
    setSelectedNode(node);
    setIsPanelOpen(true);
    if (node.data?.nodeType === 'integration') {
      setParamsJson(JSON.stringify(node.data.params || {}, null, 2));
    }
  }, []);

  const onPaneClick = useCallback(() => {
    setSelectedNode(null);
    setIsPanelOpen(false);
  }, []);

  useEffect(() => {
    if (!selectedNode) {
      return;
    }

    const nextSelectedNode = nodes.find((node) => node.id === selectedNode.id) ?? null;

    if (nextSelectedNode !== selectedNode) {
      setSelectedNode(nextSelectedNode);
    }
  }, [nodes, selectedNode]);

  const updateSelectedNodeData = useCallback(
    (field: 'label' | 'description' | 'nodeType', value: string) => {
      if (!selectedNode) {
        return;
      }

      setNodes((currentNodes) =>
        currentNodes.map((node) => {
          if (node.id !== selectedNode.id) {
            return node;
          }

          const updatedNode = {
            ...node,
            data: {
              ...node.data,
              [field]: value,
            },
          };
          return updatedNode;
        })
      );
    },
    [selectedNode, setNodes]
  );

  const addNode = (nodeType: keyof typeof nodeTypesConfig) => {
    const newNode: Node = {
      id: `node-${Date.now()}`,
      type: 'custom',
      position: { x: 400, y: 100 + nodes.length * 50 },
      data: {
        label: `New ${nodeTypesConfig[nodeType].label}`,
        nodeType,
        description: 'Configure this node',
      },
    };
    setNodes((nds) => [...nds, newNode]);
  };

  const serializeNodes = () => nodes.map((n) => ({
    id: n.id,
    type: n.type,
    position: n.position,
    data: n.data,
  }));

  const loadWorkflow = async (id: string) => {
    try {
      const res = await apiClient.getWorkflow(id);
      const wf = res.data as any;
      setWorkflowId(wf.id);
      setWorkflowName(wf.name);
      setNodes(wf.nodes?.length ? wf.nodes : initialNodes);
      setEdges(wf.edges?.length ? wf.edges : []);
      toast({ title: 'Workflow loaded', description: wf.name });
    } catch (e: any) {
      toast({ title: 'Failed to load workflow', description: e?.message, variant: 'destructive' });
    }
  };

  const handleNewWorkflow = () => {
    setWorkflowId(null);
    setWorkflowName('My Workflow');
    setNodes(initialNodes);
    setEdges(initialEdges);
    setSelectedNode(null);
    setIsPanelOpen(false);
  };

  const applyTemplate = async (template: any) => {
    if (template.workflow_definition) {
      const def = template.workflow_definition;
      setWorkflowId(null);
      setWorkflowName(template.name);
      setNodes(def.nodes || initialNodes);
      setEdges(def.edges || []);
      toast({ title: 'Template applied', description: template.name });
      return;
    }
    try {
      const res = await apiClient.cloneWorkflowTemplate(template.id);
      const wf = (res.data as any)?.workflow || res.data;
      if (wf?.id) {
        await loadWorkflow(wf.id);
      }
    } catch {
      toast({ title: 'Template loaded', description: 'Start from scratch and add integration nodes.' });
      setWorkflowId(null);
      setWorkflowName(template.name);
      setNodes([{
        id: 'node-trigger',
        type: 'custom',
        position: { x: 250, y: 50 },
        data: { label: 'Start', nodeType: 'trigger', description: 'Workflow entry point' },
      }]);
      setEdges([]);
    }
  };

  const deleteSelectedNode = () => {
    if (!selectedNode) return;
    setNodes((nds) => nds.filter((n) => n.id !== selectedNode.id));
    setEdges((eds) => eds.filter((e) => e.source !== selectedNode.id && e.target !== selectedNode.id));
    setSelectedNode(null);
    setIsPanelOpen(false);
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const payload = {
        name: workflowName,
        description: 'Visual integration workflow',
        nodes: serializeNodes(),
        edges,
        status: 'active',
      };
      if (workflowId) {
        await apiClient.updateWorkflow(workflowId, payload);
      } else {
        const res = await apiClient.createWorkflow(payload);
        setWorkflowId((res.data as any).id);
      }
      await loadSavedWorkflows();
      toast({ title: 'Workflow saved' });
    } catch (e: any) {
      toast({ title: 'Failed to save workflow', description: e?.message, variant: 'destructive' });
    } finally {
      setIsSaving(false);
    }
  };

  const handleExecute = async () => {
    setIsExecuting(true);
    try {
      let id = workflowId;
      if (!id) {
        const res = await apiClient.createWorkflow({
          name: workflowName,
          nodes: serializeNodes(),
          edges,
          status: 'active',
        });
        id = (res.data as any).id;
        setWorkflowId(id);
      }
      const execRes = await apiClient.executeWorkflow(id!, { input_data: {} });
      const exec = execRes.data as any;
      toast({
        title: exec.status === 'completed' ? 'Workflow completed' : 'Workflow finished',
        description: exec.error_message || `Status: ${exec.status}`,
        variant: exec.status === 'failed' ? 'destructive' : 'default',
      });
    } catch (e: any) {
      toast({ title: 'Workflow execution failed', description: e?.response?.data?.error || e?.message, variant: 'destructive' });
    } finally {
      setIsExecuting(false);
    }
  };

  const addIntegrationNode = (tool: any) => {
    const newNode: Node = {
      id: `node-${Date.now()}`,
      type: 'custom',
      position: { x: 400, y: 100 + nodes.length * 50 },
      data: {
        label: tool.name,
        nodeType: 'integration',
        description: tool.description,
        tool_name: tool.name,
        params: {},
      },
    };
    setNodes((nds) => [...nds, newNode]);
  };

  return (
    <AppLayout>
      <div className="h-[calc(100vh-7rem)] flex flex-col">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-center justify-between mb-4"
        >
          <div className="flex items-center gap-4">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-indigo-500 to-purple-500">
              <Workflow className="h-5 w-5 text-white" />
            </div>
            <div>
              <Input
                value={workflowName}
                onChange={(e) => setWorkflowName(e.target.value)}
                className="text-lg font-semibold bg-transparent border-none p-0 h-auto focus-visible:ring-0"
              />
              <p className="text-sm text-muted-foreground">Visual Workflow Builder</p>
            </div>
            <Badge variant="secondary">{workflowId ? 'Saved' : 'Draft'}</Badge>
            {savedWorkflows.length > 0 && (
              <Select value={workflowId || ''} onValueChange={(v) => v && loadWorkflow(v)}>
                <SelectTrigger className="w-48 h-8">
                  <SelectValue placeholder="Open workflow..." />
                </SelectTrigger>
                <SelectContent>
                  {savedWorkflows.map((w) => (
                    <SelectItem key={w.id} value={w.id}>{w.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
            <Button variant="ghost" size="sm" onClick={handleNewWorkflow}>New</Button>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" className="gap-2">
              <Undo className="h-4 w-4" />
            </Button>
            <Button variant="outline" size="sm" className="gap-2">
              <Redo className="h-4 w-4" />
            </Button>
            <div className="w-px h-6 bg-border mx-2" />
            <Button variant="outline" size="sm" className="gap-2">
              <Upload className="h-4 w-4" />
              Import
            </Button>
            <Button variant="outline" size="sm" className="gap-2">
              <Download className="h-4 w-4" />
              Export
            </Button>
            <Button variant="outline" size="sm" className="gap-2" onClick={handleSave} disabled={isSaving}>
              <Save className="h-4 w-4" />
              {isSaving ? 'Saving...' : 'Save'}
            </Button>
            <Button className="gap-2 bg-gradient-to-r from-green-500 to-emerald-500 hover:opacity-90" onClick={handleExecute} disabled={isExecuting}>
              <Play className="h-4 w-4" />
              {isExecuting ? 'Running...' : 'Execute'}
            </Button>
          </div>
        </motion.div>

        {/* Main Content */}
        <div className="flex-1 flex gap-4 overflow-hidden">
          {/* Node Palette */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            className="w-64 shrink-0"
          >
            <Card className="h-full">
              <CardHeader className="pb-2">
                <CardTitle className="text-sm">Node Palette</CardTitle>
                <CardDescription className="text-xs">Drag to add nodes</CardDescription>
              </CardHeader>
              <CardContent className="p-2">
                <Tabs defaultValue="nodes">
                  <TabsList className="w-full grid grid-cols-3">
                    <TabsTrigger value="nodes" className="text-xs">Nodes</TabsTrigger>
                    <TabsTrigger value="integrations" className="text-xs">Integrations</TabsTrigger>
                    <TabsTrigger value="templates" className="text-xs">Templates</TabsTrigger>
                  </TabsList>
                  
                  <TabsContent value="nodes" className="mt-2">
                    <ScrollArea className="h-[calc(100vh-22rem)]">
                      <div className="space-y-2 pr-4">
                        {Object.entries(nodeTypesConfig).map(([key, config]) => {
                          const Icon = config.icon;
                          return (
                            <motion.button
                              key={key}
                              whileHover={{ scale: 1.02 }}
                              whileTap={{ scale: 0.98 }}
                              onClick={() => addNode(key as keyof typeof nodeTypesConfig)}
                              className="w-full flex items-center gap-3 p-3 rounded-lg border border-dashed hover:border-primary hover:bg-primary/5 transition-colors text-left"
                            >
                              <div className={cn("flex h-8 w-8 items-center justify-center rounded-lg", config.color)}>
                                <Icon className="h-4 w-4 text-white" />
                              </div>
                              <div>
                                <p className="text-sm font-medium">{config.label}</p>
                                <p className="text-xs text-muted-foreground">Click to add</p>
                              </div>
                            </motion.button>
                          );
                        })}
                      </div>
                    </ScrollArea>
                  </TabsContent>

                  <TabsContent value="integrations" className="mt-2">
                    <ScrollArea className="h-[calc(100vh-22rem)]">
                      <div className="space-y-2 pr-4">
                        {integrationTools.length === 0 ? (
                          <p className="text-xs text-muted-foreground p-2">Connect integrations first, then add tools here.</p>
                        ) : integrationTools.map((tool) => (
                          <motion.button
                            key={`${tool.integration_id}-${tool.name}`}
                            whileHover={{ scale: 1.02 }}
                            onClick={() => addIntegrationNode(tool)}
                            className="w-full flex flex-col gap-1 p-3 rounded-lg border border-dashed hover:border-cyan-500 hover:bg-cyan-500/5 text-left"
                          >
                            <span className="text-sm font-medium">{tool.name}</span>
                            <span className="text-xs text-muted-foreground">{tool.integration_name}</span>
                          </motion.button>
                        ))}
                      </div>
                    </ScrollArea>
                  </TabsContent>

                  <TabsContent value="templates" className="mt-2">
                    <ScrollArea className="h-[calc(100vh-22rem)]">
                      <div className="space-y-2 pr-4">
                        {workflowTemplates.map((template) => (
                          <motion.button
                            key={template.id}
                            whileHover={{ scale: 1.02 }}
                            whileTap={{ scale: 0.98 }}
                            onClick={() => applyTemplate(template)}
                            className="w-full flex items-center justify-between p-3 rounded-lg border hover:border-primary hover:bg-primary/5 transition-colors text-left"
                          >
                            <div>
                              <p className="text-sm font-medium">{template.name}</p>
                              <p className="text-xs text-muted-foreground">
                                {template.category || 'template'}
                                {template.workflow_definition?.nodes?.length
                                  ? ` • ${template.workflow_definition.nodes.length} nodes`
                                  : template.nodes ? ` • ${template.nodes} nodes` : ''}
                              </p>
                            </div>
                            <ChevronRight className="h-4 w-4 text-muted-foreground" />
                          </motion.button>
                        ))}
                      </div>
                    </ScrollArea>
                  </TabsContent>
                </Tabs>
              </CardContent>
            </Card>
          </motion.div>

          {/* Canvas */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="flex-1 rounded-xl border bg-muted/30 overflow-hidden"
            ref={reactFlowWrapper}
          >
            <ReactFlow
              nodes={nodes}
              edges={edges}
              onNodesChange={onNodesChange}
              onEdgesChange={onEdgesChange}
              onConnect={onConnect}
              onNodeClick={onNodeClick}
              onPaneClick={onPaneClick}
              nodeTypes={nodeTypes}
              fitView
              snapToGrid
              snapGrid={[15, 15]}
              className="bg-dots-pattern"
            >
              <Background gap={20} size={1} color="hsl(var(--muted-foreground) / 0.1)" />
              <Controls className="!bg-background !border !shadow-lg !rounded-xl" />
              <MiniMap
                className="!bg-background !border !shadow-lg !rounded-xl"
                nodeColor={(node) => {
                  const config = nodeTypesConfig[node.data?.nodeType as keyof typeof nodeTypesConfig];
                  return config ? config.color.replace('bg-', '') : '#6366f1';
                }}
              />
              
              <Panel position="top-right" className="flex gap-2">
                <Button variant="outline" size="icon" className="bg-background">
                  <ZoomIn className="h-4 w-4" />
                </Button>
                <Button variant="outline" size="icon" className="bg-background">
                  <ZoomOut className="h-4 w-4" />
                </Button>
                <Button variant="outline" size="icon" className="bg-background">
                  <Maximize2 className="h-4 w-4" />
                </Button>
              </Panel>
            </ReactFlow>
          </motion.div>

          {/* Properties Panel */}
          <Sheet open={isPanelOpen} onOpenChange={setIsPanelOpen}>
            <SheetContent className="w-80">
              <SheetHeader>
                <SheetTitle>Node Properties</SheetTitle>
                <SheetDescription>
                  Configure the selected node
                </SheetDescription>
              </SheetHeader>
              {selectedNode && (
                <div className="space-y-4 mt-4">
                  <div className="space-y-2">
                    <Label>Node Name</Label>
                    <Input
                      value={String(selectedNode.data.label ?? '')}
                      onChange={(event) => updateSelectedNodeData('label', event.target.value)}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>Description</Label>
                    <Textarea
                      value={String(selectedNode.data.description ?? '')}
                      onChange={(event) => updateSelectedNodeData('description', event.target.value)}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>Type</Label>
                    <Select
                      value={String(selectedNode.data.nodeType ?? 'action')}
                      onValueChange={(value) => updateSelectedNodeData('nodeType', value)}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {Object.entries(nodeTypesConfig).map(([key, config]) => (
                          <SelectItem key={key} value={key}>
                            <div className="flex items-center gap-2">
                              <config.icon className="h-4 w-4" />
                              {config.label}
                            </div>
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  
                  {selectedNode.data.nodeType === 'integration' && (
                    <>
                      <div className="space-y-2">
                        <Label>Integration Tool</Label>
                        <Select
                          value={String(selectedNode.data.tool_name ?? '')}
                          onValueChange={(value) => {
                            const tool = integrationTools.find((t) => t.name === value);
                            setNodes((current) => current.map((node) => node.id === selectedNode.id
                              ? { ...node, data: { ...node.data, tool_name: value, label: value, description: tool?.description || '' } }
                              : node));
                          }}
                        >
                          <SelectTrigger><SelectValue placeholder="Select tool" /></SelectTrigger>
                          <SelectContent>
                            {integrationTools.map((t) => (
                              <SelectItem key={t.name} value={t.name}>{t.name}</SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="space-y-2">
                        <Label>Tool Parameters (JSON)</Label>
                        <Textarea
                          className="font-mono text-xs"
                          rows={5}
                          value={paramsJson}
                          onChange={(e) => {
                            setParamsJson(e.target.value);
                            try {
                              const parsed = JSON.parse(e.target.value || '{}');
                              setNodes((current) => current.map((node) => node.id === selectedNode.id
                                ? { ...node, data: { ...node.data, params: parsed } }
                                : node));
                            } catch { /* invalid json while typing */ }
                          }}
                        />
                      </div>
                    </>
                  )}

                  <div className="pt-4 border-t flex gap-2">
                    <Button variant="outline" size="sm" className="flex-1 gap-2" onClick={() => {
                      if (!selectedNode) return;
                      const copy: Node = {
                        ...selectedNode,
                        id: `node-${Date.now()}`,
                        position: { x: selectedNode.position.x + 40, y: selectedNode.position.y + 40 },
                      };
                      setNodes((nds) => [...nds, copy]);
                    }}>
                      <Copy className="h-4 w-4" />
                      Duplicate
                    </Button>
                    <Button variant="destructive" size="sm" className="flex-1 gap-2" onClick={deleteSelectedNode}>
                      <Trash2 className="h-4 w-4" />
                      Delete
                    </Button>
                  </div>
                </div>
              )}
            </SheetContent>
          </Sheet>
        </div>
      </div>
    </AppLayout>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useMultiModel } from '@/hooks/useMultiModel';
import { useWebSocket } from '@/hooks/useWebSocket';
import { FeedbackWidget } from './FeedbackWidget';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Send, Loader2, User, Bot } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { oneDark } from 'react-syntax-highlighter/dist/esm/styles/prism';
import { toast } from 'sonner';

interface WsMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  provider?: string;
  model?: string;
  timestamp: Date;
}

interface ChatInterfaceProps {
  sessionId: string;
  agentId?: string;
}

export function ChatInterface({ sessionId, agentId }: ChatInterfaceProps) {
  const [messages, setMessages] = useState<WsMessage[]>([]);
  const [input, setInput] = useState('');
  const { chat, loading } = useMultiModel();
  const { connectionStatus, lastMessage } = useWebSocket({
    url: `${process.env.NEXT_PUBLIC_WS_URL || 'ws://localhost:8000'}/ws/session/${sessionId}/`,
  });
  const isConnected = connectionStatus === 'connected';
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Handle WebSocket messages
  useEffect(() => {
    if (lastMessage) {
      const wsMessage = lastMessage as unknown as WsMessage;
      setMessages((prev) => [
        ...prev,
        {
          id: wsMessage.id,
          role: 'assistant',
          content: wsMessage.content,
          timestamp: new Date(wsMessage.timestamp),
        },
      ]);
    }
  }, [lastMessage]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMessage: WsMessage = {
      id: `user-${Date.now()}`,
      role: 'user',
      content: input,
      timestamp: new Date(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput('');

    try {
      const response = await chat(
        [
          ...messages.map((m) => ({ role: m.role, content: m.content })),
          { role: 'user', content: input },
        ],
        agentId ? { model_preference: agentId } : undefined
      );

      if (response) {
        setMessages((prev) => [
          ...prev,
          {
            id: `assistant-${Date.now()}`,
            role: 'assistant',
            content: response.response,
            provider: response.provider,
            model: response.model_used,
            timestamp: new Date(),
          },
        ]);
      }
    } catch (error) {
      toast.error('Failed to send message');
      console.error('Chat error:', error);
    }
  };

  return (
    <div className="flex flex-col h-full">
      {/* Connection Status */}
      <div className="flex items-center justify-between p-4 border-b">
        <h2 className="text-lg font-semibold">AI Chat</h2>
        <Badge variant={isConnected ? 'default' : 'secondary'}>
          {isConnected ? 'Connected' : 'Connecting...'}
        </Badge>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((message) => (
          <Card key={message.id} className={message.role === 'user' ? 'ml-12' : 'mr-12'}>
            <CardContent className="p-4">
              <div className="flex items-start space-x-3">
                <div
                  className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${
                    message.role === 'user' ? 'bg-blue-500' : 'bg-purple-500'
                  }`}
                >
                  {message.role === 'user' ? (
                    <User className="h-4 w-4 text-white" />
                  ) : (
                    <Bot className="h-4 w-4 text-white" />
                  )}
                </div>
                <div className="flex-1 space-y-2">
                  <div className="prose max-w-none prose-sm dark:prose-invert">
                    {message.role === 'assistant' ? (
                      <ReactMarkdown 
                        remarkPlugins={[remarkGfm]}
                        components={{
                          code: ({ className, children, node: _node, ref: _ref, ...props }) => {
                            const match = /language-(\w+)/.exec(className || '');
                            const isInline = !match && !String(children).includes('\n');
                            return !isInline && match ? (
                              <SyntaxHighlighter
                                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                                style={oneDark as any}
                                language={match[1]}
                                PreTag="div"
                                className="rounded-md text-sm"
                                {...props}
                              >
                                {String(children).replace(/\n$/, '')}
                              </SyntaxHighlighter>
                            ) : (
                              <code className="bg-muted px-1 py-0.5 rounded text-sm font-mono" {...props}>
                                {children}
                              </code>
                            );
                          },
                          h1: ({ children }) => <h1 className="text-lg font-bold mb-2 mt-4 first:mt-0">{children}</h1>,
                          h2: ({ children }) => <h2 className="text-base font-bold mb-2 mt-3 first:mt-0">{children}</h2>,
                          h3: ({ children }) => <h3 className="text-sm font-bold mb-1 mt-2 first:mt-0">{children}</h3>,
                          p: ({ children }) => <p className="mb-2 last:mb-0">{children}</p>,
                          ul: ({ children }) => <ul className="list-disc list-inside mb-2 space-y-1">{children}</ul>,
                          ol: ({ children }) => <ol className="list-decimal list-inside mb-2 space-y-1">{children}</ol>,
                          li: ({ children }) => <li className="ml-4">{children}</li>,
                          strong: ({ children }) => <strong className="font-semibold">{children}</strong>,
                          em: ({ children }) => <em className="italic">{children}</em>,
                          blockquote: ({ children }) => <blockquote className="border-l-4 border-muted-foreground/30 pl-4 italic my-2">{children}</blockquote>
                        }}
                      >
                        {message.content}
                      </ReactMarkdown>
                    ) : (
                      <p className="whitespace-pre-wrap">{message.content}</p>
                    )}
                  </div>
                  
                  {/* Model Badge */}
                  {message.provider && (
                    <div className="flex items-center space-x-2 text-xs text-muted-foreground">
                      <Badge variant="outline" className="text-xs">
                        {message.provider}
                      </Badge>
                      {message.model && (
                        <span>{message.model}</span>
                      )}
                    </div>
                  )}

                  {/* Feedback Widget for assistant messages */}
                  {message.role === 'assistant' && (
                    <FeedbackWidget
                      messageId={message.id}
                      agentId={agentId}
                      sessionId={sessionId}
                    />
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="border-t p-4">
        <div className="flex space-x-2">
          <Textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSend();
              }
            }}
            placeholder="Type your message... (Shift+Enter for new line)"
            rows={3}
            className="flex-1"
          />
          <Button
            onClick={handleSend}
            disabled={loading || !input.trim()}
            size="icon"
            className="h-auto"
          >
            {loading ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Send className="h-4 w-4" />
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { ChartContainer, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';
import { LineChart, Line, XAxis, YAxis } from 'recharts';

interface AgentMetric {
  timestamp: number;
  latency: number;
  throughput: number;
  accuracy: number;
}

const chartConfig = {
  latency: { label: "Latency (ms)", color: "#3B82F6" },
  throughput: { label: "Throughput", color: "#10B981" },
  accuracy: { label: "Accuracy (%)", color: "#8B5CF6" }
};

export default function AgentChart({ metrics }: { metrics: AgentMetric[] }) {
  const chartData = metrics.map(metric => ({
    time: new Date(metric.timestamp).toLocaleTimeString(),
    latency: metric.latency,
    throughput: metric.throughput,
    accuracy: metric.accuracy * 100
  }));

  return (
    <Card className="bg-white/50 dark:bg-slate-800/50 border-slate-200/50 dark:border-slate-700/50 backdrop-blur-sm">
      <CardHeader>
        <CardTitle className="text-lg">Agent Performance</CardTitle>
      </CardHeader>
      <CardContent>
        <ChartContainer config={chartConfig} className="h-[300px]">
          <LineChart data={chartData}>
            <XAxis dataKey="time" />
            <YAxis />
            <ChartTooltip content={({ content: _content, ...props }) => <ChartTooltipContent {...props} />} />
            <Line type="monotone" dataKey="latency" stroke="var(--color-latency)" strokeWidth={2} />
            <Line type="monotone" dataKey="throughput" stroke="var(--color-throughput)" strokeWidth={2} />
            <Line type="monotone" dataKey="accuracy" stroke="var(--color-accuracy)" strokeWidth={2} />
          </LineChart>
        </ChartContainer>
      </CardContent>
    </Card>
  );
}

'use client'

import React, { useState, useEffect } from 'react'
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card'
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/components/ui/tabs'
import {
  Badge,
} from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Textarea } from '@/components/ui/textarea'
import {
  Alert,
  AlertDescription,
  AlertTitle,
} from '@/components/ui/alert'
import { Progress } from '@/components/ui/progress'
import {
  Activity,
  Brain,
  Cpu,
  TrendingUp,
  AlertTriangle,
  CheckCircle,
  Clock,
  Zap,
  Users,
  BarChart3,
  Eye,
  MessageSquare,
  Settings,
  Loader2,
  RefreshCw,
} from 'lucide-react'
import { useToast } from '@/hooks/use-toast'

interface AgentConfiguration {
  accuracy?: number
  avg_response_time?: number
  features?: string[]
  performance_metrics?: Record<string, unknown>
}

interface Agent {
  id: string
  name: string
  type: string
  status: string
  capabilities: string[]
  configuration: AgentConfiguration
}

interface PerformanceData {
  agent_id: string
  success_rate: number
  avg_response_time: number
  accuracy: number
  total_executions: number
  error_types: Record<string, number>
}

interface AgentRecommendation {
  agent: Agent
  suitability_score: number
  recommendation_reason: string
}

interface SystemOverview {
  agents: {
    total: number
    utilization_rate: number
    by_status: Record<string, number>
  }
  tasks: {
    total: number
    success_rate: number
    by_status: Record<string, number>
  }
  sessions: {
    total: number
    active: number
  }
  messages: {
    total: number
    agent_messages: number
  }
}

interface Insight {
  type: 'positive' | 'warning' | 'info'
  category: string
  title: string
  description: string
  impact: 'low' | 'medium' | 'high'
  actionable: boolean
  suggested_action?: string
}

interface Recommendation {
  type: string
  category: string
  title: string
  description: string
  priority: 'low' | 'medium' | 'high'
  estimated_impact: string
  actions?: string[]
}

interface DashboardData {
  overview: SystemOverview
  agent_metrics: Record<string, unknown>
  performance_trends: Record<string, unknown>
  insights: Insight[]
  recommendations: Recommendation[]
}

const SmartAgentDashboard: React.FC = () => {
  const [agents, setAgents] = useState<Agent[]>([])
  const [dashboardData, setDashboardData] = useState<DashboardData | null>(null)
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null)
  const [performanceData, setPerformanceData] = useState<PerformanceData | null>(null)
  const [agentRecommendations, setAgentRecommendations] = useState<AgentRecommendation[]>([])
  const [loading, setLoading] = useState(false)
  const [refreshing, setRefreshing] = useState(false)
  
  // Task Selection Form
  const [taskType, setTaskType] = useState('')
  const [taskDescription, setTaskDescription] = useState('')
  const [requirements, setRequirements] = useState('')

  const { toast } = useToast()

  const taskTypes = [
    'text', 'vision', 'image', 'reasoning', 'logic', 
    'action', 'execution', 'memory', 'storage', 
    'orchestration', 'coordination'
  ]

  useEffect(() => {
    const initData = async () => {
      setLoading(true)
      try {
        await Promise.all([
          loadAgents(),
          loadDashboardData()
        ])
      } catch (error) {
        console.error('Failed to load dashboard data:', error)
        toast({
          title: 'Error',
          description: 'Failed to load dashboard data',
          variant: 'destructive',
        })
      } finally {
        setLoading(false)
      }
    }
    initData()
  }, [toast])

  const loadInitialData = async () => {
    setLoading(true)
    try {
      await Promise.all([
        loadAgents(),
        loadDashboardData()
      ])
    } catch (error) {
      console.error('Failed to load dashboard data:', error)
      toast({
        title: 'Error',
        description: 'Failed to load dashboard data',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const loadAgents = async () => {
    try {
      const response = await fetch('/api/agents/agents/')
      const data = await response.json()
      setAgents(data.results || data)
    } catch (error) {
      console.error('Error loading agents:', error)
    }
  }

  const loadDashboardData = async () => {
    try {
      const response = await fetch('/api/agents/analytics/dashboard_data/')
      const data = await response.json()
      setDashboardData(data)
    } catch (error) {
      console.error('Error loading dashboard data:', error)
    }
  }

  const refreshData = async () => {
    setRefreshing(true)
    await loadInitialData()
    setRefreshing(false)
    
    toast({
      title: 'Data Refreshed',
      description: 'Dashboard data has been updated',
    })
  }

  const selectBestAgent = async () => {
    if (!taskType || !taskDescription) {
      toast({
        title: 'Missing Information',
        description: 'Please provide task type and description',
        variant: 'destructive',
      })
      return
    }

    setLoading(true)
    try {
      const response = await fetch('/api/agents/smart-agents/select_best_agent/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          task_type: taskType,
          description: taskDescription,
          requirements: requirements ? JSON.parse(requirements) : {}
        })
      })

      const data = await response.json()
      
      if (response.ok) {
        setSelectedAgent(data.selected_agent)
        toast({
          title: 'Agent Selected',
          description: `${data.selected_agent.name} has been selected for your task`,
        })
      } else {
        toast({
          title: 'Selection Failed',
          description: data.error || 'Failed to select agent',
          variant: 'destructive',
        })
      }
    } catch (error) {
      console.error('Failed to select agent:', error)
      toast({
        title: 'Error',
        description: 'Failed to select agent',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const getAgentRecommendations = async () => {
    if (!taskType || !taskDescription) {
      toast({
        title: 'Missing Information',
        description: 'Please provide task type and description',
        variant: 'destructive',
      })
      return
    }

    setLoading(true)
    try {
      const response = await fetch('/api/agents/smart-agents/get_agent_recommendations/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          task_type: taskType,
          description: taskDescription,
          count: 5
        })
      })

      const data = await response.json()
      
      if (response.ok) {
        setAgentRecommendations(data.recommendations)
      } else {
        toast({
          title: 'Failed to get recommendations',
          description: data.error || 'Unknown error occurred',
          variant: 'destructive',
        })
      }
    } catch (error) {
      console.error('Failed to get agent recommendations:', error)
      toast({
        title: 'Error',
        description: 'Failed to get agent recommendations',
        variant: 'destructive',
      })
    } finally {
      setLoading(false)
    }
  }

  const loadAgentPerformance = async (agentId: string) => {
    try {
      const response = await fetch(`/api/agents/smart-agents/${agentId}/performance_analysis/`)
      const data = await response.json()
      
      if (response.ok) {
        setPerformanceData(data.performance_data)
      }
    } catch (error) {
      console.error('Error loading agent performance:', error)
    }
  }

  const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
      case 'active': return 'bg-green-500'
      case 'idle': return 'bg-blue-500'
      case 'processing': return 'bg-yellow-500'
      case 'error': return 'bg-red-500'
      case 'offline': return 'bg-gray-500'
      default: return 'bg-gray-500'
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status.toLowerCase()) {
      case 'active': return <CheckCircle className="w-4 h-4" />
      case 'processing': return <Loader2 className="w-4 h-4 animate-spin" />
      case 'error': return <AlertTriangle className="w-4 h-4" />
      default: return <Clock className="w-4 h-4" />
    }
  }

  if (loading && !dashboardData) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <Loader2 className="w-8 h-8 animate-spin mx-auto mb-4" />
          <p>Loading Smart Agent Dashboard...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6 p-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Smart Agent Dashboard</h1>
          <p className="text-muted-foreground">
            Intelligent agent selection and performance monitoring
          </p>
        </div>
        <Button 
          onClick={refreshData} 
          disabled={refreshing}
          variant="outline"
          className="flex items-center gap-2"
        >
          <RefreshCw className={`w-4 h-4 ${refreshing ? 'animate-spin' : ''}`} />
          Refresh
        </Button>
      </div>

      <Tabs defaultValue="overview" className="space-y-4">
        <TabsList>
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="selection">Agent Selection</TabsTrigger>
          <TabsTrigger value="performance">Performance</TabsTrigger>
          <TabsTrigger value="insights">Insights</TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="space-y-4">
          {dashboardData?.overview && (
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">Total Agents</CardTitle>
                  <Users className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">
                    {dashboardData.overview.agents.total}
                  </div>
                  <p className="text-xs text-muted-foreground">
                    {Math.round(dashboardData.overview.agents.utilization_rate * 100)}% utilization
                  </p>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">Active Tasks</CardTitle>
                  <Activity className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">
                    {dashboardData.overview.tasks.total}
                  </div>
                  <p className="text-xs text-muted-foreground">
                    {Math.round(dashboardData.overview.tasks.success_rate * 100)}% success rate
                  </p>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">Active Sessions</CardTitle>
                  <MessageSquare className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">
                    {dashboardData.overview.sessions.active}
                  </div>
                  <p className="text-xs text-muted-foreground">
                    {dashboardData.overview.sessions.total} total
                  </p>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">Messages</CardTitle>
                  <MessageSquare className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">
                    {dashboardData.overview.messages.total}
                  </div>
                  <p className="text-xs text-muted-foreground">
                    {dashboardData.overview.messages.agent_messages} from agents
                  </p>
                </CardContent>
              </Card>
            </div>
          )}

          {/* Agent Status Grid */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Cpu className="w-5 h-5" />
                Agent Status Overview
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {agents.map((agent) => (
                  <div 
                    key={agent.id}
                    className="p-4 border rounded-lg hover:shadow-md transition-shadow cursor-pointer"
                    onClick={() => loadAgentPerformance(agent.id)}
                  >
                    <div className="flex items-center justify-between mb-2">
                      <h3 className="font-semibold truncate">{agent.name}</h3>
                      <div className="flex items-center gap-1">
                        {getStatusIcon(agent.status)}
                        <div className={`w-2 h-2 rounded-full ${getStatusColor(agent.status)}`} />
                      </div>
                    </div>
                    <p className="text-sm text-muted-foreground mb-2">{agent.type}</p>
                    <div className="flex flex-wrap gap-1">
                      {agent.capabilities.slice(0, 2).map((capability, idx) => (
                        <Badge key={idx} variant="secondary" className="text-xs">
                          {capability}
                        </Badge>
                      ))}
                      {agent.capabilities.length > 2 && (
                        <Badge variant="secondary" className="text-xs">
                          +{agent.capabilities.length - 2}
                        </Badge>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="selection" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Brain className="w-5 h-5" />
                Smart Agent Selection
              </CardTitle>
              <CardDescription>
                Let AI select the best agent for your task automatically
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="task-type">Task Type</Label>
                  <Select value={taskType} onValueChange={setTaskType}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select task type" />
                    </SelectTrigger>
                    <SelectContent>
                      {taskTypes.map((type) => (
                        <SelectItem key={type} value={type}>
                          {type}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                
                <div className="space-y-2">
                  <Label htmlFor="requirements">Requirements (JSON)</Label>
                  <Input
                    id="requirements"
                    placeholder='{"min_accuracy": 0.9}'
                    value={requirements}
                    onChange={(e) => setRequirements(e.target.value)}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="task-description">Task Description</Label>
                <Textarea
                  id="task-description"
                  placeholder="Describe your task in detail..."
                  value={taskDescription}
                  onChange={(e) => setTaskDescription(e.target.value)}
                  rows={3}
                />
              </div>

              <div className="flex gap-2">
                <Button onClick={selectBestAgent} disabled={loading}>
                  {loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Zap className="w-4 h-4 mr-2" />}
                  Select Best Agent
                </Button>
                <Button onClick={getAgentRecommendations} variant="outline" disabled={loading}>
                  {loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Eye className="w-4 h-4 mr-2" />}
                  Get Recommendations
                </Button>
              </div>

              {selectedAgent && (
                <Alert>
                  <CheckCircle className="h-4 w-4" />
                  <AlertTitle>Selected Agent</AlertTitle>
                  <AlertDescription>
                    <strong>{selectedAgent.name}</strong> ({selectedAgent.type}) has been selected as the best match for your task.
                  </AlertDescription>
                </Alert>
              )}

              {agentRecommendations.length > 0 && (
                <Card>
                  <CardHeader>
                    <CardTitle>Agent Recommendations</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-3">
                      {agentRecommendations.map((rec) => (
                        <div key={rec.agent.id} className="flex items-center justify-between p-3 border rounded">
                          <div>
                            <h4 className="font-semibold">{rec.agent.name}</h4>
                            <p className="text-sm text-muted-foreground">{rec.agent.type}</p>
                            <p className="text-xs text-muted-foreground mt-1">{rec.recommendation_reason}</p>
                          </div>
                          <div className="text-right">
                            <div className="text-sm font-semibold">
                              {Math.round(rec.suitability_score * 100)}%
                            </div>
                            <Progress value={rec.suitability_score * 100} className="w-20 mt-1" />
                          </div>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="performance" className="space-y-4">
          {performanceData && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <BarChart3 className="w-5 h-5" />
                  Agent Performance Analysis
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                  <div className="text-center">
                    <div className="text-2xl font-bold">
                      {Math.round(performanceData.success_rate * 100)}%
                    </div>
                    <p className="text-sm text-muted-foreground">Success Rate</p>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold">
                      {performanceData.avg_response_time.toFixed(1)}s
                    </div>
                    <p className="text-sm text-muted-foreground">Avg Response Time</p>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold">
                      {Math.round(performanceData.accuracy * 100)}%
                    </div>
                    <p className="text-sm text-muted-foreground">Accuracy</p>
                  </div>
                </div>

                <div className="space-y-4">
                  <h4 className="font-semibold">Error Analysis</h4>
                  <div className="space-y-2">
                    {Object.entries(performanceData.error_types).map(([errorType, count]) => (
                      <div key={errorType} className="flex justify-between items-center">
                        <span className="capitalize">{errorType.replace('_', ' ')}</span>
                        <Badge variant="destructive">{count}</Badge>
                      </div>
                    ))}
                  </div>
                </div>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        <TabsContent value="insights" className="space-y-4">
          {dashboardData?.insights && (
            <div className="space-y-4">
              {dashboardData.insights.map((insight, index) => (
                <Alert key={index} className={
                  insight.type === 'positive' ? 'border-green-200' :
                  insight.type === 'warning' ? 'border-yellow-200' : 
                  'border-blue-200'
                }>
                  {insight.type === 'positive' ? <TrendingUp className="h-4 w-4" /> :
                   insight.type === 'warning' ? <AlertTriangle className="h-4 w-4" /> :
                   <Activity className="h-4 w-4" />}
                  <AlertTitle>{insight.title}</AlertTitle>
                  <AlertDescription>
                    {insight.description}
                    {insight.suggested_action && (
                      <div className="mt-2 p-2 bg-muted rounded text-sm">
                        <strong>Suggested Action:</strong> {insight.suggested_action}
                      </div>
                    )}
                  </AlertDescription>
                </Alert>
              ))}
            </div>
          )}

          {dashboardData?.recommendations && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Settings className="w-5 h-5" />
                  Optimization Recommendations
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {dashboardData.recommendations.map((rec, index) => (
                    <div key={index} className="border rounded-lg p-4">
                      <div className="flex justify-between items-start mb-2">
                        <h4 className="font-semibold">{rec.title}</h4>
                        <Badge variant={
                          rec.priority === 'high' ? 'destructive' :
                          rec.priority === 'medium' ? 'default' : 
                          'secondary'
                        }>
                          {rec.priority} priority
                        </Badge>
                      </div>
                      <p className="text-sm text-muted-foreground mb-3">{rec.description}</p>
                      {rec.actions && (
                        <div>
                          <p className="text-sm font-semibold mb-1">Recommended Actions:</p>
                          <ul className="text-sm space-y-1">
                            {rec.actions.map((action, actionIndex) => (
                              <li key={actionIndex} className="flex items-center gap-2">
                                <div className="w-1.5 h-1.5 bg-current rounded-full" />
                                {action}
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}
        </TabsContent>
      </Tabs>
    </div>
  )
}

export default SmartAgentDashboard

